{
  "scenarios": [
    {
      "id": "interest-positive-01",
      "operation": {"method": "POST", "path": "/interest"},
      "category": "positive",
      "purpose": "Enviar a única representação válida do request: objeto JSON vazio.",
      "request": {"bodyKind": "json", "bodyJson": {}},
      "expectedFromContract": {
        "requestSchema": "#/components/schemas/InterestRequest",
        "responses": [
          {
            "status": 200,
            "condition": "Observação permitida disponível e nenhuma falha técnica conhecida.",
            "schema": "#/components/schemas/InterestEnvelope",
            "obligations": [
              "Resposta application/json, objeto fechado com track=interest, completeness=not_attested, durability=unknown e outputs obrigatórios.",
              "outputs.availability deve ser available; items é array obrigatório, podendo ser vazio.",
              "Cada item deve obedecer a GeneratedInterestTransaction, incluindo todos os campos obrigatórios string e vedação de propriedades adicionais."
            ]
          },
          {
            "status": 500,
            "condition": "Falha técnica conhecida no momento da resposta, com precedência sobre 200 e 503.",
            "schema": "#/components/schemas/InterfaceError",
            "obligations": [
              "Erro da trilha interest, category=technical_failure, completeness=not_attested e durability=unknown.",
              "availableContent é opcional, somente com observação efetivamente disponível e conforme InterestEnvelope."
            ]
          },
          {
            "status": 503,
            "condition": "Nenhuma observação representável e nenhuma falha técnica conhecida.",
            "schema": "#/components/schemas/InterfaceError",
            "obligations": [
              "Erro da trilha interest, category=content_unavailable, completeness=not_attested e durability=unknown.",
              "Ausência de observação não equivale a items vazio observado."
            ]
          }
        ]
      },
      "limitations": [
        "O request vazio e fechado oferece apenas uma instância JSON válida, limitando a diversidade.",
        "Request válido não garante 200; não há entrada pública para determinar disponibilidade ou provocar falha técnica.",
        "Não são inferidos valores de transações, quantidade de itens, completude ou durabilidade."
      ]
    },
    {
      "id": "interest-negative-01",
      "operation": {"method": "POST", "path": "/interest"},
      "category": "negative",
      "purpose": "Verificar a obrigação de presença do corpo, distinguindo ausência de objeto vazio.",
      "request": {"bodyKind": "absent"},
      "expectedFromContract": {
        "status": 400,
        "mediaType": "application/json",
        "schema": "#/components/schemas/InterfaceError",
        "obligations": [
          "Corpo ausente viola requestBody.required=true.",
          "Erro da trilha interest conforme InterestInterfaceError, com category=request_representation, completeness=not_attested e durability=unknown.",
          "Propriedades adicionais são proibidas; availableContent é opcional somente nas condições contratuais."
        ]
      },
      "limitations": [
        "Cenário deliberadamente inválido quanto à representação; não exercita regras de negócio.",
        "Não há garantia contratual de ausência de efeitos, rollback ou retry."
      ]
    },
    {
      "id": "interest-negative-02",
      "operation": {"method": "POST", "path": "/interest"},
      "category": "negative",
      "purpose": "Distinguir null JSON de objeto vazio obrigatório.",
      "request": {"bodyKind": "json", "bodyJson": null},
      "expectedFromContract": {
        "status": 400,
        "mediaType": "application/json",
        "schema": "#/components/schemas/InterfaceError",
        "obligations": [
          "null não satisfaz InterestRequest, cujo tipo é object.",
          "Erro da trilha interest conforme InterestInterfaceError, com category=request_representation, completeness=not_attested e durability=unknown.",
          "Propriedades adicionais são proibidas; availableContent é opcional somente nas condições contratuais."
        ]
      },
      "limitations": [
        "Variação restrita ao tipo JSON, sem campos de negócio.",
        "Não se presume mensagem textual de erro ou diagnóstico interno."
      ]
    },
    {
      "id": "interest-boundary-01",
      "operation": {"method": "POST", "path": "/interest"},
      "category": "boundary",
      "purpose": "Explorar o limite de representação entre coleção vazia e objeto vazio: array vazio continua inválido.",
      "request": {"bodyKind": "json", "bodyJson": []},
      "expectedFromContract": {
        "status": 400,
        "mediaType": "application/json",
        "schema": "#/components/schemas/InterfaceError",
        "obligations": [
          "Array vazio não satisfaz o tipo object de InterestRequest.",
          "Erro da trilha interest conforme InterestInterfaceError, com category=request_representation, completeness=not_attested e durability=unknown.",
          "Propriedades adicionais são proibidas; availableContent é opcional somente nas condições contratuais."
        ]
      },
      "limitations": [
        "Boundary de representação, também negativo; não é limite numérico de negócio.",
        "Não existem campos de request ou limites de tamanho declarados que permitam maior diversidade válida."
      ]
    },
    {
